'use strict';

function selectCandidates(candidates, criteria) {
  if (!Array.isArray(candidates)) throw new TypeError('candidates must be an array');
  if (criteria === null || typeof criteria !== 'object' || Array.isArray(criteria)) {
    throw new TypeError('criteria must be an object');
  }

  function text(value, field) {
    if (typeof value !== 'string' || value.trim().length === 0) {
      throw new TypeError(field + ' must be a non-empty string');
    }
    return value.trim();
  }
  function skills(value) {
    if (!Array.isArray(value)) throw new TypeError('skills must be an array');
    const result = value.map((item) => text(item, 'skill'));
    if (new Set(result).size !== result.length) throw new RangeError('duplicate skill');
    return result;
  }
  function score(value, field) {
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(field + ' must be a finite number');
    }
    if (value < 0 || value > 100) throw new RangeError(field + ' is out of range');
    return value;
  }

  const minScore = Object.prototype.hasOwnProperty.call(criteria, 'minScore')
    ? score(criteria.minScore, 'minScore') : 0;
  const required = Object.prototype.hasOwnProperty.call(criteria, 'requiredSkills')
    ? skills(criteria.requiredSkills) : [];
  const order = Object.prototype.hasOwnProperty.call(criteria, 'order')
    ? criteria.order : 'name';
  if (!['name', 'score-asc', 'score-desc'].includes(order)) {
    throw new RangeError('unsupported order');
  }

  const ids = new Set();
  const normalized = candidates.map((candidate, index) => {
    if (candidate === null || typeof candidate !== 'object' || Array.isArray(candidate)) {
      throw new TypeError('candidate must be an object');
    }
    const id = text(candidate.id, 'id');
    if (ids.has(id)) throw new RangeError('duplicate candidate id');
    ids.add(id);
    return {
      id,
      name: text(candidate.name, 'name'),
      score: score(candidate.score, 'score'),
      skills: skills(candidate.skills),
      index
    };
  });

  const selected = normalized.filter((candidate) =>
    candidate.score >= minScore &&
    required.some((skill) => candidate.skills.includes(skill))
  );
  selected.sort((a, b) => {
    let comparison;
    if (order === 'name') comparison = a.name < b.name ? -1 : a.name > b.name ? 1 : 0;
    else if (order === 'score-asc') comparison = a.score - b.score;
    else comparison = b.score - a.score;
    return comparison || a.index - b.index;
  });
  return selected.map(({ id, name, score: value, skills: list }) =>
    ({ id, name, score: value, skills: [...list] }));
}

module.exports = { selectCandidates };

