'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Reflect.ownKeys(api), ['selectCandidates']);
const { selectCandidates } = api;

const skills1 = Object.freeze([' JS ', 'Node']);
const candidates = Object.freeze([
  Object.freeze({ id: ' c1 ', name: ' Zoe ', score: 90, skills: skills1, ignored: true }),
  Object.freeze({ id: 'c2', name: 'Amy', score: 90, skills: Object.freeze(['JS', 'SQL']) }),
  Object.freeze({ id: 'c3', name: 'Amy', score: 75, skills: Object.freeze(['JS']) }),
  Object.freeze({ id: 'c4', name: 'Bob', score: 100, skills: Object.freeze(['SQL']) })
]);
const criteria = Object.freeze({
  minScore: 70,
  requiredSkills: Object.freeze([' JS ']),
  order: 'name'
});
const selected = selectCandidates(candidates, criteria);
assert.deepStrictEqual(selected, [
  { id: 'c2', name: 'Amy', score: 90, skills: ['JS', 'SQL'] },
  { id: 'c3', name: 'Amy', score: 75, skills: ['JS'] },
  { id: 'c1', name: 'Zoe', score: 90, skills: ['JS', 'Node'] }
]);
assert.deepStrictEqual(skills1, [' JS ', 'Node']);

assert.deepStrictEqual(selectCandidates(candidates, { order: 'score-asc' }).map((x) => x.id),
  ['c3', 'c1', 'c2', 'c4']);
assert.deepStrictEqual(selectCandidates(candidates, { order: 'score-desc' }).map((x) => x.id),
  ['c4', 'c1', 'c2', 'c3']);
assert.deepStrictEqual(selectCandidates([], {}), []);
assert.deepStrictEqual(selectCandidates(candidates, { requiredSkills: ['js'] }), []);
assert.deepStrictEqual(selectCandidates([{ id: 'x', name: 'X', score: 0, skills: [] }], {}), [
  { id: 'x', name: 'X', score: 0, skills: [] }
]);

const copy1 = selectCandidates(candidates, {});
const copy2 = selectCandidates(candidates, {});
assert.notStrictEqual(copy1, copy2);
assert.notStrictEqual(copy1[0], copy2[0]);
assert.notStrictEqual(copy1[0].skills, copy2[0].skills);
copy1[0].skills.push('changed');
assert.strictEqual(copy2[0].skills.includes('changed'), false);

assert.throws(() => selectCandidates(null, {}), TypeError);
assert.throws(() => selectCandidates([], null), TypeError);
assert.throws(() => selectCandidates([null], {}), TypeError);
assert.throws(() => selectCandidates([{ id: 1, name: 'x', score: 1, skills: [] }], {}), TypeError);
assert.throws(() => selectCandidates([{ id: ' ', name: 'x', score: 1, skills: [] }], {}), TypeError);
assert.throws(() => selectCandidates([{ id: 'x', name: '', score: 1, skills: [] }], {}), TypeError);
assert.throws(() => selectCandidates([{ id: 'x', name: 'x', score: NaN, skills: [] }], {}), TypeError);
assert.throws(() => selectCandidates([{ id: 'x', name: 'x', score: -1, skills: [] }], {}), RangeError);
assert.throws(() => selectCandidates([{ id: 'x', name: 'x', score: 101, skills: [] }], {}), RangeError);
assert.throws(() => selectCandidates([{ id: 'x', name: 'x', score: 1, skills: 'JS' }], {}), TypeError);
assert.throws(() => selectCandidates([{ id: 'x', name: 'x', score: 1, skills: [' '] }], {}), TypeError);
assert.throws(() => selectCandidates([{ id: 'x', name: 'x', score: 1, skills: ['JS', ' JS '] }], {}), RangeError);
assert.throws(() => selectCandidates([
  { id: 'x', name: 'A', score: 1, skills: [] },
  { id: ' x ', name: 'B', score: 2, skills: [] }
], {}), RangeError);
assert.throws(() => selectCandidates([], { minScore: '50' }), TypeError);
assert.throws(() => selectCandidates([], { minScore: Infinity }), TypeError);
assert.throws(() => selectCandidates([], { minScore: 101 }), RangeError);
assert.throws(() => selectCandidates([], { requiredSkills: ['A', ' A '] }), RangeError);
assert.throws(() => selectCandidates([], { order: 'random' }), RangeError);

